<?php
require_once dirname(__DIR__).'/config/database.php';require_once dirname(__DIR__).'/includes/layout.php';require_login('student');$uid=(int)current_user()['id'];
$q=$pdo->prepare('SELECT COUNT(*) FROM enrollments WHERE user_id=?');$q->execute([$uid]);$enrolled=(int)$q->fetchColumn();$q=$pdo->prepare("SELECT COUNT(*) FROM payments WHERE user_id=? AND status='pending'");$q->execute([$uid]);$pending=(int)$q->fetchColumn();$q=$pdo->prepare('SELECT c.*,e.enrolled_at FROM enrollments e JOIN courses c ON c.id=e.course_id WHERE e.user_id=? ORDER BY e.enrolled_at DESC LIMIT 3');$q->execute([$uid]);$recent=$q->fetchAll();
$courses=$pdo->query("SELECT * FROM courses WHERE status='active' ORDER BY title")->fetchAll();$selectedId=(int)($_GET['course']??0);$selected=null;foreach($courses as $c)if((int)$c['id']===$selectedId)$selected=$c;
$q=$pdo->prepare('SELECT course_id FROM enrollments WHERE user_id=?');$q->execute([$uid]);$enrolledIds=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));
start_page('Student overview','dashboard'); ?>
<section class="hero-panel mb-5"><p class="eyebrow !text-[#d8bd74]">WELCOME BACK</p><h2 class="mt-2 text-2xl font-extrabold text-white">Hello, <?= e(explode(' ',current_user()['full_name'])[0]) ?>.</h2><p class="mt-2 max-w-xl text-sm leading-6 text-slate-200">Your next opportunity starts with one good lesson. Continue learning or explore a course that moves you forward.</p><a class="btn-primary mt-5 !bg-[#137c78]" href="<?= e(app_url('courses.php')) ?>">Explore courses</a></section>
<div class="mb-6 grid gap-4 sm:grid-cols-3"><div class="stat-card"><p class="stat-label">Courses enrolled</p><p class="stat-value"><?= $enrolled ?></p></div><div class="stat-card"><p class="stat-label">Payments awaiting confirmation</p><p class="stat-value"><?= $pending ?></p></div><div class="stat-card"><p class="stat-label">Enrollment fee</p><p class="stat-value">KSh 5</p></div></div>
<?php if($selected): $isEnrolled=in_array((int)$selected['id'],$enrolledIds,true); ?><section class="card mb-6"><div class="flex flex-wrap justify-between gap-3"><div><span class="course-code"><?= e($selected['code']) ?></span><h2 class="card-title mt-2 text-xl"><?= e($selected['title']) ?></h2><p class="muted mt-2 max-w-2xl leading-6"><?= e($selected['description']) ?></p><p class="mt-3 text-xs text-slate-500">Duration: <?= e($selected['duration']) ?> · Enrollment fee: KSh 5.00</p></div><?php if($isEnrolled): ?><a class="btn-primary self-start" href="<?= e(app_url('student/learning.php')) ?>">Open course</a><?php endif ?></div><?php if(!$isEnrolled): ?><form method="post" action="<?= e(app_url('enroll.php')) ?>" class="mt-5 grid gap-4 border-t border-slate-100 pt-5 sm:grid-cols-[1fr_1fr_auto] sm:items-end"><?= csrf_field() ?><input type="hidden" name="course_id" value="<?= (int)$selected['id'] ?>"><div><label class="field-label" for="provider">Payment method</label><select class="field" id="provider" name="provider"><option value="mpesa">M-Pesa STK Push (KSh 5)</option><option value="paystack">Paystack (KSh 5)</option></select></div><div><label class="field-label" for="phone">M-Pesa phone <span class="font-normal text-slate-400">(if selected)</span></label><input class="field" id="phone" name="phone" type="tel" placeholder="07xx xxx xxx" value="<?= e(current_user()['phone']??'') ?>"></div><button class="btn-primary">Pay KSh 5 & enroll</button></form><?php endif ?></section><?php endif ?>
<div class="mb-3 flex items-center justify-between"><h2 class="card-title">Available courses</h2><a class="text-sm font-bold text-teal-700" href="<?= e(app_url('courses.php')) ?>">Browse all →</a></div><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><?php foreach(array_slice($courses,0,3) as $course): ?><article class="card course-card"><span class="course-code"><?= e($course['code']) ?></span><h3 class="mt-3 text-lg font-bold text-slate-800"><?= e($course['title']) ?></h3><p class="mt-2 flex-1 text-sm leading-6 text-slate-600"><?= e($course['description']) ?></p><div class="mt-4 flex items-center justify-between border-t border-slate-100 pt-3"><span class="text-xs text-slate-500"><?= e($course['duration']) ?></span><?php if(in_array((int)$course['id'],$enrolledIds,true)): ?><a class="text-xs font-bold text-teal-700" href="<?= e(app_url('student/learning.php')) ?>">Enrolled · Open</a><?php else: ?><a class="text-xs font-bold text-teal-700" href="<?= e(app_url('student/dashboard.php?course='.(int)$course['id'])) ?>">Details & enroll →</a><?php endif ?></div></article><?php endforeach ?></div><?php if($recent): ?><section class="mt-7"><div class="mb-3 flex justify-between"><h2 class="card-title">Your learning</h2><a class="text-sm font-bold text-teal-700" href="<?= e(app_url('student/learning.php')) ?>">View all</a></div><div class="table-wrap"><table><thead><tr><th>Course</th><th>Code</th><th>Enrolled</th><th></th></tr></thead><tbody><?php foreach($recent as $r): ?><tr><td class="font-semibold text-slate-700"><?= e($r['title']) ?></td><td><?= e($r['code']) ?></td><td><?= e(date('M j, Y',strtotime($r['enrolled_at']))) ?></td><td><a class="font-bold text-teal-700" href="<?= e(app_url('student/learning.php')) ?>">Open</a></td></tr><?php endforeach ?></tbody></table></div></section><?php endif ?><?php end_page(); ?>
